WITH filtered AS (SELECT *, QUARTER(started_at) AS started_at_quarter, COALESCE(browser, 'NONE') AS browser_clean FROM sessions WHERE started_at >= TIMESTAMP '2023-06-18 17:00:00' AND browser IS NOT NULL), latest_match AS (SELECT s.*, x.web_event_event_time FROM filtered s LEFT JOIN LATERAL (SELECT c.event_time AS web_event_event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) x ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND TO_DATE(c.event_time) >= '2025-02-22')), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM not_flagged), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT browser, DATE_TRUNC('QUARTER', started_at) AS quarter_start, customer_id, AVG(is_new_session) FILTER (WHERE device = 'tablet') AS tablet_avg_is_new_session, COUNT(CASE WHEN browser = 'Chrome' THEN 1 END) AS chrome_count, SUM(started_at_quarter) FILTER (WHERE country = 'SG') AS sg_total_started_at_quarter, COUNT(*) AS event_count, ROUND(AVG(session_no), 2) AS avg_session_no, ROUND(AVG(is_new_session), 2) AS avg_is_new_session FROM sessionized GROUP BY browser, DATE_TRUNC('QUARTER', started_at), customer_id HAVING ROUND(AVG(is_new_session), 2) > 0;
